// QSPI Memory Interface. Provides a memory-mapped interface to up to two SPI/DSPI/QSPI flash or PSRAM devices. Also provides a serial interface for programming and configuration of the external device.
type QMI_Type struct {
	DIRECT_CSR volatile.Register32 // 0x0
	DIRECT_TX  volatile.Register32 // 0x4
	DIRECT_RX  volatile.Register32 // 0x8
	M0_TIMING  volatile.Register32 // 0xC
	M0_RFMT    volatile.Register32 // 0x10
	M0_RCMD    volatile.Register32 // 0x14
	M0_WFMT    volatile.Register32 // 0x18
	M0_WCMD    volatile.Register32 // 0x1C
	M1_TIMING  volatile.Register32 // 0x20
	M1_RFMT    volatile.Register32 // 0x24
	M1_RCMD    volatile.Register32 // 0x28
	M1_WFMT    volatile.Register32 // 0x2C
	M1_WCMD    volatile.Register32 // 0x30
	ATRANS0    volatile.Register32 // 0x34
	ATRANS1    volatile.Register32 // 0x38
	ATRANS2    volatile.Register32 // 0x3C
	ATRANS3    volatile.Register32 // 0x40
	ATRANS4    volatile.Register32 // 0x44
	ATRANS5    volatile.Register32 // 0x48
	ATRANS6    volatile.Register32 // 0x4C
	ATRANS7    volatile.Register32 // 0x50
}

