// Additional registers mapped adjacent to the bootram, for use by the bootrom.
type BOOTRAM_Type struct {
	_             [2048]byte
	WRITE_ONCE0   volatile.Register32 // 0x800
	WRITE_ONCE1   volatile.Register32 // 0x804
	BOOTLOCK_STAT volatile.Register32 // 0x808
	BOOTLOCK0     volatile.Register32 // 0x80C
	BOOTLOCK1     volatile.Register32 // 0x810
	BOOTLOCK2     volatile.Register32 // 0x814
	BOOTLOCK3     volatile.Register32 // 0x818
	BOOTLOCK4     volatile.Register32 // 0x81C
	BOOTLOCK5     volatile.Register32 // 0x820
	BOOTLOCK6     volatile.Register32 // 0x824
	BOOTLOCK7     volatile.Register32 // 0x828
}

// BOOTRAM.WRITE_ONCE0: This registers always ORs writes into its current contents. Once a bit is set, it can only be cleared by a reset.
func (o *BOOTRAM_Type) SetWRITE_ONCE0(value uint32) {
	volatile.StoreUint32(&o.WRITE_ONCE0.Reg, value)
}
func (o *BOOTRAM_Type) GetWRITE_ONCE0() uint32 {
	return volatile.LoadUint32(&o.WRITE_ONCE0.Reg)
}

// BOOTRAM.WRITE_ONCE1: This registers always ORs writes into its current contents. Once a bit is set, it can only be cleared by a reset.
func (o *BOOTRAM_Type) SetWRITE_ONCE1(value uint32) {
	volatile.StoreUint32(&o.WRITE_ONCE1.Reg, value)
}
func (o *BOOTRAM_Type) GetWRITE_ONCE1() uint32 {
	return volatile.LoadUint32(&o.WRITE_ONCE1.Reg)
}

// BOOTRAM.BOOTLOCK_STAT: Bootlock status register. 1=unclaimed, 0=claimed. These locks function identically to the SIO spinlocks, but are reserved for bootrom use.
func (o *BOOTRAM_Type) SetBOOTLOCK_STAT(value uint32) {
	volatile.StoreUint32(&o.BOOTLOCK_STAT.Reg, volatile.LoadUint32(&o.BOOTLOCK_STAT.Reg)&^(0xff)|value)
}
func (o *BOOTRAM_Type) GetBOOTLOCK_STAT() uint32 {
	return volatile.LoadUint32(&o.BOOTLOCK_STAT.Reg) & 0xff
}

// BOOTRAM.BOOTLOCK0: Read to claim and check. Write to unclaim. The value returned on successful claim is 1 << n, and on failed claim is zero.
func (o *BOOTRAM_Type) SetBOOTLOCK0(value uint32) {
	volatile.StoreUint32(&o.BOOTLOCK0.Reg, value)
}
func (o *BOOTRAM_Type) GetBOOTLOCK0() uint32 {
	return volatile.LoadUint32(&o.BOOTLOCK0.Reg)
}

