type TRNG_Type struct {
	_                  [256]byte
	RNG_IMR            volatile.Register32 // 0x100
	RNG_ISR            volatile.Register32 // 0x104
	RNG_ICR            volatile.Register32 // 0x108
	TRNG_CONFIG        volatile.Register32 // 0x10C
	TRNG_VALID         volatile.Register32 // 0x110
	EHR_DATA0          volatile.Register32 // 0x114
	EHR_DATA1          volatile.Register32 // 0x118
	EHR_DATA2          volatile.Register32 // 0x11C
	EHR_DATA3          volatile.Register32 // 0x120
	EHR_DATA4          volatile.Register32 // 0x124
	EHR_DATA5          volatile.Register32 // 0x128
	RND_SOURCE_ENABLE  volatile.Register32 // 0x12C
	SAMPLE_CNT1        volatile.Register32 // 0x130
	AUTOCORR_STATISTIC volatile.Register32 // 0x134
	TRNG_DEBUG_CONTROL volatile.Register32 // 0x138
	_                  [4]byte
	TRNG_SW_RESET      volatile.Register32 // 0x140
	_                  [112]byte
	RNG_DEBUG_EN_INPUT volatile.Register32 // 0x1B4
	TRNG_BUSY          volatile.Register32 // 0x1B8
	RST_BITS_COUNTER   volatile.Register32 // 0x1BC
	RNG_VERSION        volatile.Register32 // 0x1C0
	_                  [28]byte
	RNG_BIST_CNTR_0    volatile.Register32 // 0x1E0
	RNG_BIST_CNTR_1    volatile.Register32 // 0x1E4
	RNG_BIST_CNTR_2    volatile.Register32 // 0x1E8
}

