// Glitch detector controls
type GLITCH_DETECTOR_Type struct {
	ARM         volatile.Register32 // 0x0
	DISARM      volatile.Register32 // 0x4
	SENSITIVITY volatile.Register32 // 0x8
	LOCK        volatile.Register32 // 0xC
	TRIG_STATUS volatile.Register32 // 0x10
	TRIG_FORCE  volatile.Register32 // 0x14
}

// GLITCH_DETECTOR.ARM: Forcibly arm the glitch detectors, if they are not already armed by OTP. When armed, any individual detector trigger will cause a restart of the switched core power domain's power-on reset state machine. Glitch detector triggers are recorded accumulatively in TRIG_STATUS. If the system is reset by a glitch detector trigger, this is recorded in POWMAN_CHIP_RESET. This register is Secure read/write only.
func (o *GLITCH_DETECTOR_Type) SetARM(value uint32) {
	volatile.StoreUint32(&o.ARM.Reg, volatile.LoadUint32(&o.ARM.Reg)&^(0xffff)|value)
}
func (o *GLITCH_DETECTOR_Type) GetARM() uint32 {
	return volatile.LoadUint32(&o.ARM.Reg) & 0xffff
}

