func (o *GLITCH_DETECTOR_Type) SetDISARM(value uint32) {
	volatile.StoreUint32(&o.DISARM.Reg, volatile.LoadUint32(&o.DISARM.Reg)&^(0xffff)|value)
}
func (o *GLITCH_DETECTOR_Type) GetDISARM() uint32 {
	return volatile.LoadUint32(&o.DISARM.Reg) & 0xffff
}

