func (o *OTP_Type) GetARCHSEL_CORE1() uint32 {
	return (volatile.LoadUint32(&o.ARCHSEL.Reg) & 0x2) >> 1
}
func (o *OTP_Type) SetARCHSEL_CORE0(value uint32) {
	volatile.StoreUint32(&o.ARCHSEL.Reg, volatile.LoadUint32(&o.ARCHSEL.Reg)&^(0x1)|value)
}
func (o *OTP_Type) GetARCHSEL_CORE0() uint32 {
	return volatile.LoadUint32(&o.ARCHSEL.Reg) & 0x1
}

