	// Bit mask of BOOTLOCK0 field.
	BOOTRAM_BOOTLOCK0_BOOTLOCK0_Msk = 0xffffffff

	// BOOTLOCK1: Read to claim and check. Write to unclaim. The value returned on successful claim is 1 << n, and on failed claim is zero.
	// Position of BOOTLOCK1 field.
	BOOTRAM_BOOTLOCK1_BOOTLOCK1_Pos = 0x0
	// Bit mask of BOOTLOCK1 field.
	BOOTRAM_BOOTLOCK1_BOOTLOCK1_Msk = 0xffffffff

	// BOOTLOCK2: Read to claim and check. Write to unclaim. The value returned on successful claim is 1 << n, and on failed claim is zero.
	// Position of BOOTLOCK2 field.
	BOOTRAM_BOOTLOCK2_BOOTLOCK2_Pos = 0x0
	// Bit mask of BOOTLOCK2 field.
	BOOTRAM_BOOTLOCK2_BOOTLOCK2_Msk = 0xffffffff

	// BOOTLOCK3: Read to claim and check. Write to unclaim. The value returned on successful claim is 1 << n, and on failed claim is zero.
	// Position of BOOTLOCK3 field.
	BOOTRAM_BOOTLOCK3_BOOTLOCK3_Pos = 0x0
	// Bit mask of BOOTLOCK3 field.
	BOOTRAM_BOOTLOCK3_BOOTLOCK3_Msk = 0xffffffff

	// BOOTLOCK4: Read to claim and check. Write to unclaim. The value returned on successful claim is 1 << n, and on failed claim is zero.
	// Position of BOOTLOCK4 field.
	BOOTRAM_BOOTLOCK4_BOOTLOCK4_Pos = 0x0
	// Bit mask of BOOTLOCK4 field.
	BOOTRAM_BOOTLOCK4_BOOTLOCK4_Msk = 0xffffffff

	// BOOTLOCK5: Read to claim and check. Write to unclaim. The value returned on successful claim is 1 << n, and on failed claim is zero.
	// Position of BOOTLOCK5 field.
	BOOTRAM_BOOTLOCK5_BOOTLOCK5_Pos = 0x0
	// Bit mask of BOOTLOCK5 field.
	BOOTRAM_BOOTLOCK5_BOOTLOCK5_Msk = 0xffffffff

	// BOOTLOCK6: Read to claim and check. Write to unclaim. The value returned on successful claim is 1 << n, and on failed claim is zero.
	// Position of BOOTLOCK6 field.
	BOOTRAM_BOOTLOCK6_BOOTLOCK6_Pos = 0x0
	// Bit mask of BOOTLOCK6 field.
	BOOTRAM_BOOTLOCK6_BOOTLOCK6_Msk = 0xffffffff

	// BOOTLOCK7: Read to claim and check. Write to unclaim. The value returned on successful claim is 1 << n, and on failed claim is zero.
	// Position of BOOTLOCK7 field.
	BOOTRAM_BOOTLOCK7_BOOTLOCK7_Pos = 0x0
