	OTP_ARCHSEL_CORE1_Pos = 0x1
	// Bit mask of CORE1 field.
	OTP_ARCHSEL_CORE1_Msk = 0x2
	// Bit CORE1.
	OTP_ARCHSEL_CORE1 = 0x2
	// Switch core 1 to Arm (Cortex-M33)
	OTP_ARCHSEL_CORE1_ARM = 0x0
	// Switch core 1 to RISC-V (Hazard3)
	OTP_ARCHSEL_CORE1_RISCV = 0x1
	// Position of CORE0 field.
	OTP_ARCHSEL_CORE0_Pos = 0x0
	// Bit mask of CORE0 field.
	OTP_ARCHSEL_CORE0_Msk = 0x1
	// Bit CORE0.
	OTP_ARCHSEL_CORE0 = 0x1
	// Switch core 0 to Arm (Cortex-M33)
	OTP_ARCHSEL_CORE0_ARM = 0x0
	// Switch core 0 to RISC-V (Hazard3)
	OTP_ARCHSEL_CORE0_RISCV = 0x1

